mapper.select:
SELECT u.id
FROM "user" u
WHERE u.id > #{after}
  AND 
  AND EXISTS (SELECT 1 FROM member_platform_bindings b WHERE b.btn_user_id = u.id)
ORDER BY u.id LIMIT #{limit}

mapper.update:
UPDATE "user" u SET roles = array_append(u.roles, 'supporter'), supporter_auto_granted_at = now() WHERE AND u.id IN
#{id}
AND ( SELECT SUM(CASE WHEN t.currency = 'CNY' THEN t.amount WHEN t.base_currency = 'CNY' THEN t.amount_base ELSE ROUND(t.amount * COALESCE(cny.rate_to_base, CASE WHEN t.currency = t.base_currency THEN 1 ELSE original.rate_to_base END / NULLIF(base.rate_to_base, 0)), 2) END) FROM member_platform_bindings b JOIN member_transactions t ON t.provider = b.provider AND t.external_user_id = b.external_user_id LEFT JOIN currency_exchange_rates cny ON cny.base_currency = 'CNY' AND cny.quote_currency = t.currency LEFT JOIN currency_exchange_rates original ON original.base_currency = t.base_currency AND original.quote_currency = t.currency LEFT JOIN currency_exchange_rates base ON base.base_currency = t.base_currency AND base.quote_currency = 'CNY' WHERE b.btn_user_id = u.id AND ) >= #{threshold}
